import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class AssetSearchServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-automation: basic rate check (not security control)
    private static final int MAX_SEARCH_LEN = 512;

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String assetType = req.getParameter("type");
        String searchTerm = req.getParameter("q");
        String sortCol = req.getParameter("sort");

        if (searchTerm == null || searchTerm.length() > MAX_SEARCH_LEN) {
            resp.sendError(400, "Invalid search");
            return;
        }

        // Validate assetType against whitelist
        if (!isValidAssetType(assetType)) {
            resp.sendError(400, "Invalid asset type");
            return;
        }

        // Sort column - validated against known columns
        String safeSortCol = validateSortColumn(sortCol);

        // Build query - searchTerm is used in LIKE clause
        // Note: assetType is whitelisted, sortCol is whitelisted
        // searchTerm goes through prepared statement... except for the
        // full-text search path which uses native query syntax
        String results = executeSearch(assetType, searchTerm, safeSortCol);

        resp.setContentType("application/json");
        resp.getWriter().write(results);
    }

    private String executeSearch(String assetType, String searchTerm, String sortCol)
            throws ServletException {

        // PostgreSQL full-text search with ts_query
        // The searchTerm is passed to plainto_tsquery for safe parsing...
        // BUT we also support "advanced" mode with raw tsquery syntax
        // when the search contains operators like & | !

        boolean advancedMode = containsTsQueryOperators(searchTerm);

        String sql;
        if (advancedMode) {
            // Advanced: use to_tsquery which accepts pre-formatted query
            // Developer note: to_tsquery will throw on invalid syntax,
            // so this acts as implicit validation (it doesn't - SQL injection
            // is possible by closing the tsquery context)
            sql = "SELECT id, name, description, asset_type FROM assets "
                + "WHERE asset_type = '" + assetType + "' "
                + "AND textsearch @@ to_tsquery('english', '" + searchTerm + "') "
                + "ORDER BY " + sortCol + " LIMIT 50";
        } else {
            sql = "SELECT id, name, description, asset_type FROM assets "
                + "WHERE asset_type = ? "
                + "AND textsearch @@ plainto_tsquery('english', ?) "
                + "ORDER BY " + sortCol + " LIMIT 50";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            StringBuilder sb = new StringBuilder("[");

            if (advancedMode) {
                // Raw statement for advanced tsquery mode
                try (Statement stmt = conn.createStatement();
                     ResultSet rs = stmt.executeQuery(sql)) {
                    sb.append(formatResults(rs));
                }
            } else {
                try (PreparedStatement ps = conn.prepareStatement(sql)) {
                    ps.setString(1, assetType);
                    ps.setString(2, searchTerm);
                    try (ResultSet rs = ps.executeQuery()) {
                        sb.append(formatResults(rs));
                    }
                }
            }
            sb.append("]");
            return sb.toString();
        } catch (SQLException e) {
            throw new ServletException("Search failed", e);
        }
    }

    private boolean containsTsQueryOperators(String s) {
        return s.contains("&") || s.contains("|") || s.contains("!");
    }

    private boolean isValidAssetType(String type) {
        if (type == null) return false;
        return type.matches("^(hardware|software|network|facility|data)$");
    }

    private String validateSortColumn(String col) {
        if (col == null) return "name";
        switch (col) {
            case "name": case "id": case "asset_type": case "description":
                return col;
            default: return "name";
        }
    }

    private String formatResults(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append(String.format(
                "{\"id\":%d,\"name\":\"%s\",\"desc\":\"%s\",\"type\":\"%s\"}",
                rs.getInt("id"),
                rs.getString("name").replace("\"", "\\\""),
                rs.getString("description").replace("\"", "\\\""),
                rs.getString("asset_type")
            ));
            first = false;
        }
        return sb.toString();
    }
}
